// This file is used to specify the contract address for the G4m3 contract
// Different networks will have different contract addresses

// Network-specific contract addresses
const addresses = {
  // For localhost, we use an empty string - this allows the frontend to use 
  // whatever address is in the artifacts
  localhost: "",
  
  // Polygon Amoy testnet address
  amoy: "0x149D4C0578A04c3A1D3c5cB9821EFC5bfe25E965",
  
  // Ethereum Mainnet address (placeholder for future deployment)
  mainnet: "" // To be filled in after mainnet deployment
};

// Detect which network we're on
const getNetworkType = () => {
  // Check if we're in a browser environment
  if (typeof window === 'undefined') return 'localhost';
  
  // GitHub Pages or HTTPS is likely Amoy testnet for now
  if (window.location.hostname.includes('github.io') || window.location.protocol === 'https:') {
    return 'amoy';
  }
  
  // Default to localhost for local development
  return 'localhost';
};

// Dynamic contract address based on the detected network
const networkType = getNetworkType();
const address = addresses[networkType] || addresses.localhost;

// Fall back to the default localhost address if the selected network has no address set
module.exports = address || "0x5FC8d32690cc91D4c39d9d3abcBD16989F875707";